-- Load production.FactCommodityOutput (fact).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/production/FactCommodityOutput.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [production].[LoadFactCommodityOutput]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([FactCommodityOutput_SK]), 0)
                              FROM [production].[FactCommodityOutput] WHERE [FactCommodityOutput_SK] > 0);

    MERGE [production].[FactCommodityOutput] AS target
    USING (
        SELECT
            CAST(s.[CommodityProduction_BK] AS int) AS [CommodityProduction_BK],
            CAST(s.[DimFacility_SK] AS bigint) AS [DimFacility_SK],
            CAST(s.[DimMaterial_SK] AS bigint) AS [DimMaterial_SK],
            CAST(s.[CommodityDimMaterial_SK] AS bigint) AS [CommodityDimMaterial_SK],
            CAST(s.[DimDataSource_SK] AS bigint) AS [DimDataSource_SK],
            CAST(s.[StreamTypeCode] AS varchar(20)) AS [StreamTypeCode],
            CAST(s.[ReportingPeriod] AS varchar(30)) AS [ReportingPeriod],
            CAST(s.[ReportingYear] AS int) AS [ReportingYear],
            CAST(s.[ValueTonnes] AS decimal(18,4)) AS [ValueTonnes],
            CAST(s.[GradePartsPerMillion] AS decimal(18,4)) AS [GradePartsPerMillion],
            CAST(s.[RecoveryRate] AS decimal(18,8)) AS [RecoveryRate],
            CAST(s.[YieldPartsPerMillion] AS decimal(18,4)) AS [YieldPartsPerMillion],
            CAST(s.[AmountSoldTonnes] AS decimal(18,4)) AS [AmountSoldTonnes],
            CAST(s.[MetalPayableTonnes] AS decimal(18,4)) AS [MetalPayableTonnes],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[CommodityProduction_BK]) AS [NewKey]
        FROM [stage].[FactCommodityOutputSource] AS s
    ) AS source
    ON target.[CommodityProduction_BK] = source.[CommodityProduction_BK]
    WHEN MATCHED AND (
        (target.[DimFacility_SK] <> source.[DimFacility_SK] OR (target.[DimFacility_SK] IS NULL AND source.[DimFacility_SK] IS NOT NULL) OR (target.[DimFacility_SK] IS NOT NULL AND source.[DimFacility_SK] IS NULL))
        OR (target.[DimMaterial_SK] <> source.[DimMaterial_SK] OR (target.[DimMaterial_SK] IS NULL AND source.[DimMaterial_SK] IS NOT NULL) OR (target.[DimMaterial_SK] IS NOT NULL AND source.[DimMaterial_SK] IS NULL))
        OR (target.[CommodityDimMaterial_SK] <> source.[CommodityDimMaterial_SK] OR (target.[CommodityDimMaterial_SK] IS NULL AND source.[CommodityDimMaterial_SK] IS NOT NULL) OR (target.[CommodityDimMaterial_SK] IS NOT NULL AND source.[CommodityDimMaterial_SK] IS NULL))
        OR (target.[DimDataSource_SK] <> source.[DimDataSource_SK] OR (target.[DimDataSource_SK] IS NULL AND source.[DimDataSource_SK] IS NOT NULL) OR (target.[DimDataSource_SK] IS NOT NULL AND source.[DimDataSource_SK] IS NULL))
        OR (target.[StreamTypeCode] <> source.[StreamTypeCode] OR (target.[StreamTypeCode] IS NULL AND source.[StreamTypeCode] IS NOT NULL) OR (target.[StreamTypeCode] IS NOT NULL AND source.[StreamTypeCode] IS NULL))
        OR (target.[ReportingPeriod] <> source.[ReportingPeriod] OR (target.[ReportingPeriod] IS NULL AND source.[ReportingPeriod] IS NOT NULL) OR (target.[ReportingPeriod] IS NOT NULL AND source.[ReportingPeriod] IS NULL))
        OR (target.[ReportingYear] <> source.[ReportingYear] OR (target.[ReportingYear] IS NULL AND source.[ReportingYear] IS NOT NULL) OR (target.[ReportingYear] IS NOT NULL AND source.[ReportingYear] IS NULL))
        OR (target.[ValueTonnes] <> source.[ValueTonnes] OR (target.[ValueTonnes] IS NULL AND source.[ValueTonnes] IS NOT NULL) OR (target.[ValueTonnes] IS NOT NULL AND source.[ValueTonnes] IS NULL))
        OR (target.[GradePartsPerMillion] <> source.[GradePartsPerMillion] OR (target.[GradePartsPerMillion] IS NULL AND source.[GradePartsPerMillion] IS NOT NULL) OR (target.[GradePartsPerMillion] IS NOT NULL AND source.[GradePartsPerMillion] IS NULL))
        OR (target.[RecoveryRate] <> source.[RecoveryRate] OR (target.[RecoveryRate] IS NULL AND source.[RecoveryRate] IS NOT NULL) OR (target.[RecoveryRate] IS NOT NULL AND source.[RecoveryRate] IS NULL))
        OR (target.[YieldPartsPerMillion] <> source.[YieldPartsPerMillion] OR (target.[YieldPartsPerMillion] IS NULL AND source.[YieldPartsPerMillion] IS NOT NULL) OR (target.[YieldPartsPerMillion] IS NOT NULL AND source.[YieldPartsPerMillion] IS NULL))
        OR (target.[AmountSoldTonnes] <> source.[AmountSoldTonnes] OR (target.[AmountSoldTonnes] IS NULL AND source.[AmountSoldTonnes] IS NOT NULL) OR (target.[AmountSoldTonnes] IS NOT NULL AND source.[AmountSoldTonnes] IS NULL))
        OR (target.[MetalPayableTonnes] <> source.[MetalPayableTonnes] OR (target.[MetalPayableTonnes] IS NULL AND source.[MetalPayableTonnes] IS NOT NULL) OR (target.[MetalPayableTonnes] IS NOT NULL AND source.[MetalPayableTonnes] IS NULL))
    ) THEN UPDATE SET
        [DimFacility_SK] = source.[DimFacility_SK],
        [DimMaterial_SK] = source.[DimMaterial_SK],
        [CommodityDimMaterial_SK] = source.[CommodityDimMaterial_SK],
        [DimDataSource_SK] = source.[DimDataSource_SK],
        [StreamTypeCode] = source.[StreamTypeCode],
        [ReportingPeriod] = source.[ReportingPeriod],
        [ReportingYear] = source.[ReportingYear],
        [ValueTonnes] = source.[ValueTonnes],
        [GradePartsPerMillion] = source.[GradePartsPerMillion],
        [RecoveryRate] = source.[RecoveryRate],
        [YieldPartsPerMillion] = source.[YieldPartsPerMillion],
        [AmountSoldTonnes] = source.[AmountSoldTonnes],
        [MetalPayableTonnes] = source.[MetalPayableTonnes],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [FactCommodityOutput_SK],
        [CommodityProduction_BK],
        [DimFacility_SK],
        [DimMaterial_SK],
        [CommodityDimMaterial_SK],
        [DimDataSource_SK],
        [StreamTypeCode],
        [ReportingPeriod],
        [ReportingYear],
        [ValueTonnes],
        [GradePartsPerMillion],
        [RecoveryRate],
        [YieldPartsPerMillion],
        [AmountSoldTonnes],
        [MetalPayableTonnes],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[CommodityProduction_BK],
        source.[DimFacility_SK],
        source.[DimMaterial_SK],
        source.[CommodityDimMaterial_SK],
        source.[DimDataSource_SK],
        source.[StreamTypeCode],
        source.[ReportingPeriod],
        source.[ReportingYear],
        source.[ValueTonnes],
        source.[GradePartsPerMillion],
        source.[RecoveryRate],
        source.[YieldPartsPerMillion],
        source.[AmountSoldTonnes],
        source.[MetalPayableTonnes],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
